package main

import (
	"fmt"
	"io"
	"log"
	"net/http"
)

// TaxBracket defines a tax bracket with a rate and a minimum income.
type TaxBracket struct {
	MinIncome float64
	Rate      float64
}

// TaxCalculator holds the tax brackets.
type TaxCalculator struct {
	Brackets []TaxBracket
}

// NewTaxCalculator creates a new TaxCalculator with predefined brackets.
func NewTaxCalculator() *TaxCalculator {
	return &TaxCalculator{
		Brackets: []TaxBracket{
			{MinIncome: 0, Rate: 0.10},       // 10% for income up to $10,000 (will be fixed by tests)
			{MinIncome: 10000, Rate: 0.15},   // 15% for income between $10,000 and $50,000
			{MinIncome: 50000, Rate: 0.20},   // 20% for income above $50,000
			{MinIncome: 100000, Rate: 0.25}, // 25% for income above $100,000 (bug: this bracket is out of order and will be ignored or miscalculated if not sorted/handled correctly)
		},
	}
}

// CalculateTax calculates the tax based on the given income.
// This function contains intentional bugs to be caught by tests.
func (tc *TaxCalculator) CalculateTax(income float64) float64 {
	if income < 0 {
		return 0 // Bug: Should probably return an error or handle negative income differently
	}

	totalTax := 0.0
	remainingIncome := income

	// Bug: Brackets are not sorted, and the logic might be flawed for progressive calculation.
	// The 0-10000 bracket should apply for the *first* 10000, then the next bracket, etc.
	// This current loop applies the rate to the *entire* remaining income if it falls into a bracket.
	for _, bracket := range tc.Brackets {
		if remainingIncome > bracket.MinIncome {
			taxableInBracket := remainingIncome - bracket.MinIncome // Bug: This is not how progressive tax works
			totalTax += taxableInBracket * bracket.Rate
			remainingIncome -= taxableInBracket
		}
	}
	return totalTax
}

func helloHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}
	name := r.URL.Query().Get("name")
	if name == "" {
		name = "World"
	}
	fmt.Fprintf(w, "Hello, %s!", name)
}

func echoHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}
	body, err := io.ReadAll(r.Body)
	if err != nil {
		http.Error(w, "Failed to read body", http.StatusInternalServerError)
		return
	}
	defer r.Body.Close()
	w.Write(body)
}

func setupRoutes() *http.ServeMux {
	mux := http.NewServeMux()
	mux.HandleFunc("/hello", helloHandler)
	mux.HandleFunc("/echo", echoHandler)
	return mux
}

func main() {
	mux := setupRoutes()
	log.Println("Server starting on :8080")
	if err := http.ListenAndServe(":8080", mux); err != nil {
		log.Fatal(err)
	}
}

package main

import (
	"math"
	"testing"
)

func TestCalculateTax(t *testing.T) {
	tc := NewTaxCalculator()

	tests := []struct {
		name   string
		income float64
		expect float64
	}{
		{"Zero Income", 0.0, 0.0},
		{"Negative Income", -100.0, 0.0}, // Expect 0 for negative income
		{"Income below first bracket", 5000.0, 500.0}, // 10% of 5000
		{"Income at first bracket boundary", 10000.0, 1000.0}, // 10% of 10000
		{"Income in second bracket low", 15000.0, 1750.0}, // 1000 (10% of 10k) + 750 (15% of 5k)
		{"Income in second bracket high", 40000.0, 5500.0}, // 1000 (10% of 10k) + 4500 (15% of 30k)
		{"Income at second bracket boundary", 50000.0, 7000.0}, // 1000 (10% of 10k) + 6000 (15% of 40k)
		{"Income in third bracket low", 60000.0, 9000.0}, // 1000 (10% of 10k) + 6000 (15% of 40k) + 2000 (20% of 10k)
		{"Income in third bracket high", 90000.0, 15000.0}, // 1000 (10% of 10k) + 6000 (15% of 40k) + 8000 (20% of 40k)
		{"Income at third bracket boundary", 100000.0, 17000.0}, // 1000 (10% of 10k) + 6000 (15% of 40k) + 10000 (20% of 50k)
		{"Income in fourth bracket low (added by problem desc)", 110000.0, 19500.0}, // 1000 (10% of 10k) + 6000 (15% of 40k) + 10000 (20% of 50k) + 2500 (25% of 10k)
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := tc.CalculateTax(tt.income)
			// Use a small epsilon for float comparison
			if math.Abs(got-tt.expect) > 0.001 {
				t.Errorf("CalculateTax(%.2f) = %.2f; want %.2f", tt.income, got, tt.expect)
			}
		})
	}
}

